{
  "components": [
    {
      "type": "claim",
      "quote": "Besides the president of the Swiss Confederation, the Federal Assembly also elects the vice president of the Federal Council.",
      "gist": "The Federal Assembly elects the vice president of the Federal Council in addition to the president."
    },
    {
      "type": "obligation",
      "quote": "The vice president is required to step in and take on all the presidial duties when the president is unable to.",
      "gist": "The vice president must assume all presidential duties if the president is unavailable."
    },
    {
      "type": "obligation",
      "quote": "The Federal Council may also assign the vice president presidential powers.",
      "gist": "The Federal Council can delegate presidential powers to the vice president."
    },
    {
      "type": "claim",
      "quote": "Presidents of the Swiss Confederation have special representational duties during their year of office.",
      "gist": "Swiss Confederation presidents have specific representational responsibilities throughout their term."
    },
    {
      "type": "claim",
      "quote": "Traditionally they give a speech at New Year and on Swiss National Day on 1 August, which is broadcast on radio and television.",
      "gist": "Swiss presidents traditionally deliver speeches on New Year's and Swiss National Day (August 1), which are broadcast on radio and TV."
    }
  ]
}
